#include <stdio.h>
#include <ctype.h>

/* Chuyển biểu thức trung tố (số, +, *, ngoặc) sang RPN bằng thuật toán shunting-yard. */
static int do_uu_tien(char op) { return op == '*' ? 2 : op == '+' ? 1 : 0; }

int main(void) {
    char bt[256];
    if (scanf("%255s", bt) != 1) return 1;

    char ngan[256];
    int top = 0, dau = 1;

    for (int i = 0; bt[i] != '\0'; ) {
        char c = bt[i];
        if (isdigit((unsigned char)c)) {
            int so = 0;
            while (isdigit((unsigned char)bt[i])) so = so * 10 + (bt[i++] - '0');
            printf(dau ? "%d" : " %d", so);
            dau = 0;
            continue;
        }
        if (c == '(') {
            ngan[top++] = c;
        } else if (c == ')') {
            while (top > 0 && ngan[top - 1] != '(') {
                printf(" %c", ngan[--top]);
            }
            if (top > 0) top--;             /* bỏ dấu ( */
        } else if (c == '+' || c == '*') {
            while (top > 0 && ngan[top - 1] != '(' && do_uu_tien(ngan[top - 1]) >= do_uu_tien(c)) {
                printf(" %c", ngan[--top]);
            }
            ngan[top++] = c;
        }
        i++;
    }
    while (top > 0) printf(" %c", ngan[--top]);
    printf("\n");
    return 0;
}
